/*
 * IS THIS ACCOUNT EMAILED ABOUT MESSAGES? (TASK-L187 §6) For the switch on
 * /settings. The account is the session's; nobody can read anybody else's.
 */
if (Inputs.userId !== undefined) {
  (async () => {
    try {
      const users = await Noodl.Records.query('_User', { objectId: { equalTo: String(Inputs.userId || '') } }, { limit: 2, plain: true });
      if (users.length !== 1) throw new Error(users.length ? 'two accounts' : 'no account');
      Outputs.on = !users[0].emailOptOutAt;
      Outputs.done();
    } catch (e) {
      console.error('[dbt:emailPreference] ' + String((e && e.message) || e));
      Outputs.failed();
    }
  })();
}
